import{_ as e,o as a,c as r,ak as d}from"./chunks/framework.BXerppJ0.js";const f=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"sidebarDepth":0},"headers":[],"relativePath":"api/index.md","filePath":"api/index.md","lastUpdated":1794593093000}'),o={name:"api/index.md"};function s(i,t,n,l,h,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">API</p><p>The technical API is for people wanting to delve a bit deeper into the parts that make up the library.</p><ul><li>Get set up quickly with the <a href="./../guide/">setup guide</a>.</li><li>Roll some dice with <a href="./../guide/notation/">notations</a>.</li></ul></div><h2 id="namespaces" tabindex="-1">Namespaces <a class="header-anchor" href="#namespaces" aria-label="Permalink to &quot;Namespaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Namespace</th><th>Description</th></tr></thead><tbody><tr><td><a href="./rpg-dice-roller/namespaces/ast/">ast</a></td><td>Expression tree nodes and notation helpers for inspecting or constructing rolls.</td></tr><tr><td><a href="./rpg-dice-roller/namespaces/dice/">dice</a></td><td>Die definitions, presets, and registries for extending dice notation.</td></tr><tr><td><a href="./rpg-dice-roller/namespaces/engines/">engines</a></td><td>Random engines for controlling how dice are rolled.</td></tr><tr><td><a href="./rpg-dice-roller/namespaces/errors/">errors</a></td><td>Error classes raised while parsing, evaluating, and importing rolls.</td></tr><tr><td><a href="./rpg-dice-roller/namespaces/modifiers/">modifiers</a></td><td>Modifier definitions, handlers, and registries for extending roll behavior.</td></tr><tr><td><a href="./rpg-dice-roller/namespaces/presenters/">presenters</a></td><td>Presenters that format evaluated rolls and their results.</td></tr><tr><td><a href="./rpg-dice-roller/namespaces/results/">results</a></td><td>Result types and helpers for inspecting evaluated expressions.</td></tr></tbody></table><h2 id="classes" tabindex="-1">Classes <a class="header-anchor" href="#classes" aria-label="Permalink to &quot;Classes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><a href="./classes/Evaluator.html">Evaluator</a></td><td>Walks the AST and builds the result tree.</td></tr><tr><td><a href="./classes/Parser.html">Parser</a></td><td>Parses dice notation into the AST.</td></tr><tr><td><a href="./classes/Roll.html">Roll</a></td><td>One evaluated notation: the result tree and its totals.</td></tr><tr><td><a href="./classes/Roller.html">Roller</a></td><td>Rolls notation and keeps a history of the rolls.</td></tr><tr><td><a href="./classes/RollHistory.html">RollHistory</a></td><td>A log of rolls.</td></tr><tr><td><a href="./classes/RollSettings.html">RollSettings</a></td><td>Resolved <code>RollOptions</code>, with the services built from them.</td></tr></tbody></table><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Interface</th><th>Description</th></tr></thead><tbody><tr><td><a href="./interfaces/EvaluatorRegistries.html">EvaluatorRegistries</a></td><td>Registries used to resolve dice and modifier handlers during evaluation.</td></tr><tr><td><a href="./interfaces/HistoryData.html">HistoryData</a></td><td>A roll history.</td></tr><tr><td><a href="./interfaces/NumberGenerator.html">NumberGenerator</a></td><td>Generates numbers in a range from a <code>RandomEngine</code>.</td></tr><tr><td><a href="./interfaces/ParserOptions.html">ParserOptions</a></td><td>Options for parsing notation.</td></tr><tr><td><a href="./interfaces/Presenter.html">Presenter</a></td><td>Turns a roll, a roll history, or a result node into any output, e.g. text, HTML or Markdown.</td></tr><tr><td><a href="./interfaces/RandomEngine.html">RandomEngine</a></td><td>A source of randomness.</td></tr><tr><td><a href="./interfaces/RollContext.html">RollContext</a></td><td>Everything that changes per roll but isn&#39;t part of the notation.</td></tr><tr><td><a href="./interfaces/RollData.html">RollData</a></td><td>A roll, with its result tree and totals.</td></tr><tr><td><a href="./interfaces/RollLimits.html">RollLimits</a></td><td>Safety limits for a single roll.</td></tr><tr><td><a href="./interfaces/RollOptions.html">RollOptions</a></td><td>How notation is parsed, rolled and presented. Every option is optional.</td></tr></tbody></table><h2 id="type-aliases" tabindex="-1">Type Aliases <a class="header-anchor" href="#type-aliases" aria-label="Permalink to &quot;Type Aliases&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type Alias</th><th>Description</th></tr></thead><tbody><tr><td><a href="./type-aliases/DieLike.html">DieLike</a></td><td>A range or faces definition with optional behaviour overrides.</td></tr><tr><td><a href="./type-aliases/Encoded.html">Encoded</a></td><td>The data with every number (except literal ones, like <code>version</code>) as an <code>EncodedNumber</code>.</td></tr><tr><td><a href="./type-aliases/EncodedExportData.html">EncodedExportData</a></td><td>Anything that has been exported.</td></tr><tr><td><a href="./type-aliases/EncodedHistoryData.html">EncodedHistoryData</a></td><td>An exported roll history: JSON-safe, with non-finite numbers tagged.</td></tr><tr><td><a href="./type-aliases/EncodedNumber.html">EncodedNumber</a></td><td>A number in exported data: a finite number as it is, otherwise a tag, e.g. <code>{ &quot;$number&quot;: &quot;Infinity&quot; }</code>, so it survives JSON (which would turn it into <code>null</code>).</td></tr><tr><td><a href="./type-aliases/EncodedRollData.html">EncodedRollData</a></td><td>An exported roll: JSON-safe, with non-finite numbers tagged.</td></tr><tr><td><a href="./type-aliases/ExportFormat.html">ExportFormat</a></td><td>A supported export format.</td></tr><tr><td><a href="./type-aliases/ExpressionNode.html">ExpressionNode</a></td><td>Any node that evaluates to a number.</td></tr><tr><td><a href="./type-aliases/ExpressionResult.html">ExpressionResult</a></td><td>A result for an expression node; individual dice and group members are nested within it.</td></tr><tr><td><a href="./type-aliases/NonFiniteNumber.html">NonFiniteNumber</a></td><td>The tag names used for non-finite numbers.</td></tr><tr><td><a href="./type-aliases/Presentable.html">Presentable</a></td><td>A roll, history, or evaluated expression result; an individual die result is not presentable.</td></tr><tr><td><a href="./type-aliases/RollerOptions.html">RollerOptions</a></td><td>Options shared by all rolls made or imported by a roller.</td></tr><tr><td><a href="./type-aliases/RollMode.html">RollMode</a></td><td>How dice are rolled.</td></tr><tr><td><a href="./type-aliases/TaggedDieResult.html">TaggedDieResult</a></td><td>A die result carrying an internal pool tag during flattened group modifier handling.</td></tr></tbody></table><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><a href="./variables/EXPORT_FORMATS.html">EXPORT_FORMATS</a></td><td>- <code>object</code>: plain JSON-safe data (<code>EncodedRollData</code> / <code>EncodedHistoryData</code>) - <code>json</code>: that data as a JSON string - <code>base64</code>: that JSON string, base64-encoded (UTF-8)</td></tr><tr><td><a href="./variables/NON_FINITE_NUMBERS.html">NON_FINITE_NUMBERS</a></td><td>The numbers JSON can&#39;t represent, by their tag.</td></tr></tbody></table><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><a href="./functions/roll.html">roll</a></td><td>Shorthand for <code>new Roll(input, options)</code>: rolls notation (or an AST) once, without a history.</td></tr></tbody></table>',14)])])}const u=e(o,[["render",s]]);export{f as __pageData,u as default};
